 exe=Path(tmp)/'apps';cmd=['g++','-std=c++17','-g','-fsanitize=address,undefined','-fno-omit-frame-pointer','-no-pie','-I'+str(t/'mocks'),'-I'+str(s),str(t/'test_app_scan.cpp'),'-o',str(exe)]
